// Helper method to count odd digits in a string
method CountOddDigits(s: string) returns (count: int)
    requires s != null
    ensures count >= 0
    ensures count == |{d | d in s | (d - '0') % 2 == 1}|
{
    count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant count == |{d | j | j in 0..i | (s[j] - '0') % 2 == 1}|
